def compute(vars):
    revenues = {
        "2019": vars["v1"],
        "2018": vars["v2"],
        "2017": vars["v3"],
    }
    qualifying_years = [
        year for year, revenue in revenues.items()
        if revenue > 500000
    ]
    return {
        "value": len(qualifying_years),
        "trace": {
            "revenues_thousand_usd": revenues,
            "threshold_thousand_usd": 500000,
            "qualifying_years": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years",
            },
        },
    }
